class Solution {
    int solve(string_view sub, int k) {
        int res = 0;
        int m = sub.size();
        for (int c = 1; c <= 26; c++) {
            int w_len = c * k;
            if (w_len > m) break;
            int freq[26] = {0};
            for (int i = 0; i < w_len; i++) freq[sub[i] - 'a']++;
            auto valid = [&]() {
                for (int x : freq) if (x != 0 && x != k) return false;
                return true;
            };
            if (valid()) res++;
            for (int i = w_len; i < m; i++) {
                freq[sub[i] - 'a']++;
                freq[sub[i - w_len] - 'a']--;
                if (valid()) res++;
            }
        }
        return res;
    }
public:
    int countCompleteSubstrings(string word, int k) {
        int n = word.size();
        int ans = 0, start = 0;
        for (int i = 1; i <= n; i++) {
            if (i == n || abs(word[i] - word[i - 1]) > 2) {
                ans += solve(string_view(word).substr(start, i - start), k);
                start = i;
            }
        }
        return ans;
    }
};

class Solution {
    int solve(String sub, int k) {
        int res = 0;
        int m = sub.length();
        for (int c = 1; c <= 26; c++) {
            int wLen = c * k;
            if (wLen > m) break;
            int[] freq = new int[26];
            for (int i = 0; i < wLen; i++) freq[sub.charAt(i) - 'a']++;
            if (isValid(freq, k)) res++;
            for (int i = wLen; i < m; i++) {
                freq[sub.charAt(i) - 'a']++;
                freq[sub.charAt(i - wLen) - 'a']--;
                if (isValid(freq, k)) res++;
            }
        }
        return res;
    }
    boolean isValid(int[] freq, int k) {
        for (int x : freq) if (x != 0 && x != k) return false;
        return true;
    }
    public int countCompleteSubstrings(String word, int k) {
        int n = word.length();
        int ans = 0, start = 0;
        for (int i = 1; i <= n; i++) {
            if (i == n || Math.abs(word.charAt(i) - word.charAt(i - 1)) > 2) {
                ans += solve(word.substring(start, i), k);
                start = i;
            }
        }
        return ans;
    }
}

