var countCompleteSubstrings = function(word, k) {
    function solve(sub) {
        let res = 0;
        const m = sub.length;
        for (let c = 1; c <= 26; c++) {
            const wLen = c * k;
            if (wLen > m) break;
            const freq = new Int32Array(26);
            for (let i = 0; i < wLen; i++) freq[sub.charCodeAt(i) - 97]++;
            function isValid() {
                for (let j = 0; j < 26; j++) if (freq[j] !== 0 && freq[j] !== k) return false;
                return true;
            }
            if (isValid()) res++;
            for (let i = wLen; i < m; i++) {
                freq[sub.charCodeAt(i) - 97]++;
                freq[sub.charCodeAt(i - wLen) - 97]--;
                if (isValid()) res++;
            }
        }
        return res;
    }
    const n = word.length;
    let ans = 0, start = 0;
    for (let i = 1; i <= n; i++) {
        if (i === n || Math.abs(word.charCodeAt(i) - word.charCodeAt(i - 1)) > 2) {
            ans += solve(word.slice(start, i));
            start = i;
        }
    }
    return ans;
};
